36	template <typename t_DataType,
37	          unsigned int t_KBufferDim,
38	          unsigned int t_ParEntriesM,
39	          unsigned int t_ParEntriesN = t_ParEntriesM,
40	          typename t_MacDataType = t_DataType>
41	class Gemm {
42	    typedef WideType<t_DataType, t_ParEntriesM> WideTypeM;
43	    typedef WideType<t_DataType, t_ParEntriesN> WideTypeN;
44	    typedef WideType<t_MacDataType, t_ParEntriesN> WideMacTypeN;
45	
46	    typedef hls::stream<typename WideTypeM::t_TypeInt> EdgeStreamM;
47	    typedef hls::stream<typename WideTypeN::t_TypeInt> EdgeStreamN;
48	    typedef hls::stream<typename WideMacTypeN::t_TypeInt> EdgeMacStreamN;
49	
50	    typedef TaggedFloat<t_DataType> TaggedDataType;
51	
52	    typedef TaggedFloat<t_MacDataType> TaggedMacType;
53	    typedef WideType<typename TaggedMacType::t_TypeInt, t_ParEntriesN> WideTaggedMacType;
54	    typedef hls::stream<typename WideTaggedMacType::t_TypeInt> TaggedMacTypeStream;
55	
56	   public:
57	    static void gemm(EdgeStreamM& p_As, EdgeStreamN& p_Bs, EdgeMacStreamN& p_sum, unsigned int p_blocks) {
58	#ifndef __SYNTHESIS__
59	        assert(t_KBufferDim >= t_ParEntriesM + t_ParEntriesN);
60	#endif
61	
62	        WindowRm<TaggedDataType, t_ParEntriesM, t_ParEntriesN> l_awin;
63	        WindowRm<TaggedDataType, t_ParEntriesN, t_ParEntriesM> l_bwin;
64	        TriangSrl<TaggedDataType, t_ParEntriesM> l_Ta;
65	        TriangSrl<TaggedDataType, t_ParEntriesN> l_Tb;
66	        l_awin.clear();
67	        l_bwin.clear();
68	        l_Ta.clear();
69	        l_Tb.clear();
70	
71	        typedef WideType<TaggedDataType, t_ParEntriesM> TaggedArrayM;
72	        typedef WideType<TaggedDataType, t_ParEntriesN> TaggedArrayN;
73	
74	        WideType<t_MacDataType, t_ParEntriesN> l_C[t_ParEntriesM];
75	#pragma HLS ARRAY_PARTITION variable = l_C dim = 1 complete
76	        WideType<t_MacDataType, t_ParEntriesN> l_Co[t_ParEntriesM];
77	#pragma HLS ARRAY_PARTITION variable = l_Co dim = 1 complete
78	
79	        for (uint32_t l = 0; l <= p_blocks; l++)
80	            for (int k = 0; k < t_KBufferDim; k++) {
81	#pragma HLS PIPELINE
82	
83	                WideType<t_DataType, t_ParEntriesM> l_A = 0;
84	                WideType<t_DataType, t_ParEntriesN> l_B = 0;
85	
86	                if (l < p_blocks) {
87	                    l_A = p_As.read();
88	                    l_B = p_Bs.read();
89	                }
90	
91	                TaggedArrayM l_avec;
92	                for (int i = 0; i < t_ParEntriesM; i++) l_avec[i] = TaggedDataType(l_A[i], k == 0);
93	                TaggedArrayN l_bvec;
94	                for (int i = 0; i < t_ParEntriesN; i++) l_bvec[i] = TaggedDataType(l_B[i], k == 0);
95	
96	                TaggedArrayM l_avec1 = l_Ta.shift(l_avec);
97	                TaggedArrayN l_bvec1 = l_Tb.shift(l_bvec);
98	
99	                (void)l_awin.shift_right(l_avec1);
100	                (void)l_bwin.shift(l_bvec1);
101	
102	                if (l > 0 && k >= t_ParEntriesN + 1 && k <= t_ParEntriesM + t_ParEntriesN) {
103	                    p_sum.write(l_Co[k - t_ParEntriesN - 1]);
104	                }
105	
106	                for (unsigned int row = 0; row < t_ParEntriesM; ++row) {
107	#pragma HLS UNROLL
108	                    TaggedArrayM l_arow = l_awin[row];
109	                    TaggedArrayN l_brow = l_bwin[row];
110	                    for (unsigned int col = 0; col < t_ParEntriesN; ++col) {
111	#pragma HLS UNROLL
112	                        t_DataType aval = l_arow[col]();
113	                        t_DataType bval = l_brow[col]();
114	                        bool aflush = l_arow[col].getFlush();
115	#ifndef __SYNTEHSIS__
116	                        bool bflush = l_brow[col].getFlush();
117	                        assert(aflush == bflush);
118	#endif
119	                        if (aflush) {
120	                            l_Co[row][col] = l_C[row][col];
121	                            l_C[row][col] = 0;
122	                        }
123	                        l_C[row][col] += aval * bval;
124	                    }
125	                }
126	            }
127	    }
128	};
