130	template <unsigned int t_KBufferDim, unsigned int t_ParEntriesM, unsigned int t_ParEntriesN>
131	class Gemm<float, t_KBufferDim, t_ParEntriesM, t_ParEntriesN, float> {
132	    typedef float t_DataType;
133	    typedef float t_MacDataType;
134	    typedef WideType<t_DataType, t_ParEntriesM> WideTypeM;
135	    typedef WideType<t_DataType, t_ParEntriesN> WideTypeN;
