138	    typedef hls::stream<typename WideTypeM::t_TypeInt> EdgeStreamM;
139	    typedef hls::stream<typename WideTypeN::t_TypeInt> EdgeStreamN;
140	    typedef hls::stream<typename WideMacTypeN::t_TypeInt> EdgeMacStreamN;
141	
142	    typedef TaggedFloat<t_DataType> TaggedDataType;
143	
144	    typedef TaggedFloat<t_MacDataType> TaggedMacType;
145	    typedef WideType<typename TaggedMacType::t_TypeInt, t_ParEntriesN> WideTaggedMacType;
146	    typedef hls::stream<typename WideTaggedMacType::t_TypeInt> TaggedMacTypeStream;
147	
148	   public:
149	    static void gemm(EdgeStreamM& p_As, EdgeStreamN& p_Bs, EdgeMacStreamN& p_sum, unsigned int p_blocks) {
150	#ifndef __SYNTHESIS__
151	        assert(t_KBufferDim >= t_ParEntriesM + t_ParEntriesN);
152	#endif
153	#pragma HLS DATAFLOW
154	        SystolicArray<t_DataType, t_KBufferDim, t_ParEntriesM, t_ParEntriesN, t_MacDataType> l_sysArr(p_blocks);
155	        l_sysArr.process(p_As, p_Bs, p_sum);
156	    }
157	};
