159	/**
160	 * @brief gemm function that returns the result vector of the multiplication of
161	 * two matrix
162	 *
163	 * @tparam t_DataType the data type of the vector entries
164	 * @tparam t_KBufferDim description to be added
165	 * @tparam t_ParEntries the number of parallelly processed entries in the input
166	 * vector
167	 *
168	 * @param p_m the number of rows of input matrix p_M
169	 * @param p_n the number of cols of input matrix p_M, as well as the number of
170	 * entries in the input vector p_x, p_n %
171	 * l_ParEntries == 0
172	 * @param p_k description to be added
173	 * @param p_A the input stream of packed Matrix entries
174	 * @param p_B the input stream of packed Matrix entries
175	 * @param p_C the output matrix
176	 */
177	template <typename t_DataType, unsigned int t_KBufferDim, unsigned int t_ParEntries>
178	void gemm(const unsigned int p_m,
179	          const unsigned int p_n,
180	          const unsigned int p_k,
181	          hls::stream<typename WideType<t_DataType, t_ParEntries>::t_TypeInt>& p_A,
182	          hls::stream<typename WideType<t_DataType, t_ParEntries>::t_TypeInt>& p_B,
183	          hls::stream<typename WideType<t_DataType, t_ParEntries>::t_TypeInt>& p_C) {
184	#pragma HLS DATAFLOW
185	#ifndef __SYNTHESIS__
186	    assert(p_m % t_ParEntries == 0);
187	    assert(p_n % t_ParEntries == 0);
188	    assert(p_k == t_KBufferDim);
189	#endif
190	    unsigned int l_blocks = p_m * p_n / t_ParEntries / t_ParEntries;
191	    Gemm<t_DataType, t_KBufferDim, t_ParEntries>::gemm(p_A, p_B, p_C, l_blocks);
192	}
193	
194	template <typename t_DataType,
195	          unsigned int t_KBufferDim,
196	          unsigned int t_ParEntries,
197	          unsigned int t_MaxSizeC,
198	          typename t_IndexType = unsigned int>
199	void gemm(const unsigned int p_m,
200	          const unsigned int p_n,
201	          const unsigned int p_k,
202	          const t_DataType p_alpha,
203	          hls::stream<typename WideType<t_DataType, t_ParEntries>::t_TypeInt>& p_A,
204	          hls::stream<typename WideType<t_DataType, t_ParEntries>::t_TypeInt>& p_B,
205	          const t_DataType p_beta,
206	          hls::stream<typename WideType<t_DataType, t_ParEntries>::t_TypeInt>& p_C,
207	          hls::stream<typename WideType<t_DataType, t_ParEntries>::t_TypeInt>& p_R) {
208	#ifndef __SYNTHESIS__
209	    assert(p_m % t_ParEntries == 0);
210	    assert(p_n % t_ParEntries == 0);
211	    assert(p_k == t_KBufferDim);
212	#endif
213	    unsigned int l_size = p_m * p_n;
214	    unsigned int l_blocks = l_size / t_ParEntries / t_ParEntries;
215	
216	    hls::stream<typename WideType<t_DataType, t_ParEntries>::t_TypeInt> l_sum, l_mat, l_betaC;
217	
218	#pragma HLS DATAFLOW
219	
220	    Gemm<t_DataType, t_KBufferDim, t_ParEntries, t_ParEntries>::gemm(p_A, p_B, l_sum, l_blocks);
221	    gemmBufferC<t_DataType, t_ParEntries, t_ParEntries, t_MaxSizeC>(p_m, p_n, l_sum, l_mat);
222	    scal<t_DataType, t_ParEntries, t_IndexType>(l_size, p_beta, p_C, l_betaC);
223	    axpy<t_DataType, t_ParEntries, t_IndexType>(l_size, p_alpha, l_mat, l_betaC, p_R);
224	}
