25	
26	#define IDX2R(i, j, ld) (((i) * (ld)) + (j))
27	#define m 64 // a - mxk matrix
28	#define n 64 // b - kxn matrix
29	#define k 64 // c - mxn matrix
30	
31	using namespace std;
32	
33	BLAS_dataType* getGoldenMat(BLAS_dataType* a, BLAS_dataType* b, BLAS_dataType* c) {
34	    BLAS_dataType* goldenC;
35	    goldenC = (BLAS_dataType*)malloc(m * n * sizeof(BLAS_dataType));
36	    for (int row = 0; row < m; row++) {
37	        for (int col = 0; col < n; col++) {
38	            BLAS_dataType l_val = 0;
39	            for (int i = 0; i < k; i++) {
40	                l_val += a[IDX2R(row, i, k)] * b[IDX2R(i, col, n)];
41	            }
42	            goldenC[IDX2R(row, col, n)] = l_val + c[IDX2R(row, col, n)];
43	        }
44	    }
45	    return goldenC;
46	}
