             uint32_t p_n,
             uint32_t p_k,
             BLAS_dataType p_alpha,
             BLAS_dataType p_beta,
             BLAS_dataType p_A[BLAS_matrixSizeA],
             BLAS_dataType p_B[BLAS_matrixSizeB],
             BLAS_dataType p_C[BLAS_matrixSizeC],
