#pragma HLS DATAFLOW
    gemmMatAMover<BLAS_dataType, BLAS_parEntries>(p_A, p_m, p_n, p_k, l_strA);
    gemmMatBMover<BLAS_dataType, BLAS_parEntries>(p_B, p_m, p_n, p_k, l_strB);
